import { Node, SyntaxKind } from 'ts-morph';
import * as log from './log.js';
const SHARP_TRANSFORMER_SOURCE = '@payloadcms/transformer-sharp';
/**
 * Detect what changes are needed in the payload config file
 */ export function detectRequiredChanges(sourceFile) {
    const result = {
        figmaObjectExists: false,
        hasAlias: false,
        hasOtherPayloadImports: false,
        needsImportChange: false
    };
    // Find buildConfig import — prefer @payloadcms/figma (already migrated) over payload
    const imports = sourceFile.getImportDeclarations();
    const payloadImport = imports.find((imp)=>imp.getModuleSpecifierValue() === '@payloadcms/figma') || imports.find((imp)=>imp.getModuleSpecifierValue() === 'payload');
    if (!payloadImport) {
        log.debug('No payload or @payloadcms/figma import found');
        result.hasBuildConfig = false;
        return result;
    }
    log.debug(`Found import from: ${payloadImport.getModuleSpecifierValue()}`);
    const moduleSpecifier = payloadImport.getModuleSpecifierValue();
    const namedImports = payloadImport.getNamedImports();
    // Determine which function name to look for based on the import source
    // - From 'payload': look for buildConfig (needs migration)
    // - From '@payloadcms/figma': look for buildFigmaConfig (already migrated)
    const expectedFunctionName = moduleSpecifier === 'payload' ? 'buildConfig' : 'buildFigmaConfig';
    const buildConfigImport = namedImports.find((ni)=>ni.getName() === expectedFunctionName);
    if (!buildConfigImport) {
        result.hasBuildConfig = false;
        return result;
    }
    // Check for alias and get the actual name used in code
    const aliasNode = buildConfigImport.getAliasNode();
    const buildConfigName = aliasNode ? aliasNode.getText() : expectedFunctionName;
    if (aliasNode) {
        result.hasAlias = true;
    }
    // Check if import needs change
    if (moduleSpecifier === 'payload') {
        result.needsImportChange = true;
        // Check if there are other imports from payload
        if (namedImports.length > 1) {
            result.hasOtherPayloadImports = true;
        }
    }
    // Find buildConfig call in export default
    // First try to find export default with the buildConfig call
    const exportAssignment = sourceFile.getFirstDescendantByKind(SyntaxKind.ExportAssignment);
    let buildConfigCall = null;
    if (exportAssignment) {
        // Look for buildConfig call in the export default
        const callExpressions = exportAssignment.getDescendantsOfKind(SyntaxKind.CallExpression);
        buildConfigCall = callExpressions.find((ce)=>{
            const expr = ce.getExpression();
            return expr.getText() === buildConfigName;
        });
    }
    // If not found in export default, search all call expressions
    if (!buildConfigCall) {
        const callExpressions = sourceFile.getDescendantsOfKind(SyntaxKind.CallExpression);
        buildConfigCall = callExpressions.find((ce)=>{
            const expr = ce.getExpression();
            return expr.getText() === buildConfigName;
        });
    }
    if (!buildConfigCall) {
        result.hasBuildConfig = false;
        return result;
    }
    // Get config object
    const configArg = buildConfigCall.getArguments()[0];
    if (!configArg || !Node.isObjectLiteralExpression(configArg)) {
        return result;
    }
    // Check for db property
    const dbProperty = configArg.getProperty('db');
    if (dbProperty) {
        const dbValue = dbProperty.getChildrenOfKind(SyntaxKind.CallExpression)[0];
        if (dbValue) {
            const adapterName = dbValue.getExpression().getText();
            // Find the import source for this adapter
            const adapterImport = imports.find((imp)=>imp.getNamedImports().some((ni)=>ni.getName() === adapterName));
            if (adapterImport) {
                result.dbProperty = {
                    adapter: adapterName,
                    importSource: adapterImport.getModuleSpecifierValue()
                };
            }
        }
    }
    // Check for secret property. The platform owns PAYLOAD_SECRET, so the
    // scaffolded `secret: process.env.PAYLOAD_SECRET` line is stripped —
    // `buildFigmaConfig` injects the value at runtime from the env var (in
    // Lambda) or the TokenStore cache (local dev).
    const secretProperty = configArg.getProperty('secret');
    if (secretProperty) {
        result.secretProperty = true;
    }
    // Check for editor property
    const editorProperty = configArg.getProperty('editor');
    if (editorProperty) {
        const editorValue = editorProperty.getChildrenOfKind(SyntaxKind.CallExpression)[0];
        if (editorValue) {
            const editorName = editorValue.getExpression().getText();
            // Find the import source
            const editorImport = imports.find((imp)=>imp.getNamedImports().some((ni)=>ni.getName() === editorName));
            if (editorImport && editorName === 'lexicalEditor') {
                // Check if it has arguments
                const args = editorValue.getArguments();
                const isDefault = args.length === 0;
                result.editorProperty = {
                    importSource: editorImport.getModuleSpecifierValue(),
                    isDefault
                };
            }
        }
    }
    // Check for sharp property
    const sharpProperty = configArg.getProperty('sharp');
    if (sharpProperty) {
        // Find the import source for sharp
        const sharpImport = imports.find((imp)=>imp.getModuleSpecifierValue() === 'sharp' || imp.getNamedImports().some((ni)=>ni.getName() === 'sharp'));
        result.sharpProperty = {
            importSource: sharpImport?.getModuleSpecifierValue() || 'sharp'
        };
    }
    if (findSharpTransformerCalls(sourceFile, configArg).length > 0) {
        result.sharpTransformer = {
            importSource: SHARP_TRANSFORMER_SOURCE
        };
    }
    // Check for figma property
    const figmaProperty = configArg.getProperty('figma');
    if (figmaProperty) {
        result.figmaObjectExists = true;
    }
    return result;
}
/**
 * Remove all comments
 * @returns true if any comments were removed
 */ function removeAllComments(sourceFile) {
    const ranges = [];
    // Recursively collect comments from node and ALL children (including tokens)
    const collectComments = (node)=>{
        node.getLeadingCommentRanges().forEach((range)=>{
            ranges.push([
                range.getPos(),
                range.getEnd()
            ]);
        });
        node.getTrailingCommentRanges().forEach((range)=>{
            ranges.push([
                range.getPos(),
                range.getEnd()
            ]);
        });
        // Process ALL children including token nodes (commas, braces, etc.)
        node.getChildren().forEach(collectComments);
    };
    collectComments(sourceFile);
    if (ranges.length === 0) {
        return false;
    }
    // Remove duplicates and sort in reverse order to avoid position shifts
    const uniqueRanges = Array.from(new Set(ranges.map((r)=>JSON.stringify(r)))).map((r)=>JSON.parse(r));
    uniqueRanges.sort((a, b)=>b[0] - a[0]);
    // Remove each comment range, extending to the full line when the comment is the only content
    for (const [pos, end] of uniqueRanges){
        const fullText = sourceFile.getFullText();
        let removeStart = pos;
        let removeEnd = end;
        // Find the start of the line containing this comment
        let lineStart = pos;
        while(lineStart > 0 && fullText[lineStart - 1] !== '\n'){
            lineStart--;
        }
        const beforeComment = fullText.substring(lineStart, pos);
        const nextNewline = fullText.indexOf('\n', end);
        const afterComment = fullText.substring(end, nextNewline === -1 ? fullText.length : nextNewline);
        // If the comment is the only content on this line, remove the entire line
        if (beforeComment.trim() === '' && afterComment.trim() === '') {
            removeStart = lineStart > 0 ? lineStart - 1 : lineStart;
            if (nextNewline !== -1) {
                removeEnd = nextNewline + 1;
            }
        }
        sourceFile.removeText(removeStart, removeEnd);
    }
    return true;
}
/**
 * Apply modifications to the source file based on detection result
 * Modifies the AST in memory - caller must call sourceFile.save()
 */ export function applyModifications(sourceFile, detection) {
    const changes = [];
    let modified = false;
    if (detection.hasBuildConfig === false || detection.hasAlias) {
        log.debug(`Skipping modifications: hasBuildConfig=${detection.hasBuildConfig}, hasAlias=${detection.hasAlias}`);
        return {
            changes: [],
            modified: false
        };
    }
    // 1. Remove all comments FIRST (before AST modifications that might shift positions)
    const hadComments = removeAllComments(sourceFile);
    if (hadComments) {
        changes.push('Removed comments');
        modified = true;
    }
    // Find the import declarations
    const imports = sourceFile.getImportDeclarations();
    const payloadImport = imports.find((imp)=>imp.getModuleSpecifierValue() === 'payload');
    // Get the buildConfig name (could be aliased)
    let buildConfigName = 'buildConfig';
    if (payloadImport) {
        const buildConfigImport = payloadImport.getNamedImports().find((ni)=>ni.getName() === 'buildConfig');
        if (buildConfigImport) {
            const aliasNode = buildConfigImport.getAliasNode();
            buildConfigName = aliasNode ? aliasNode.getText() : 'buildConfig';
        }
    }
    // Find buildConfig call in export default (prefer export default)
    const exportAssignment = sourceFile.getFirstDescendantByKind(SyntaxKind.ExportAssignment);
    let buildConfigCall = null;
    if (exportAssignment) {
        const callExpressions = exportAssignment.getDescendantsOfKind(SyntaxKind.CallExpression);
        buildConfigCall = callExpressions.find((ce)=>{
            const expr = ce.getExpression();
            return expr.getText() === buildConfigName;
        });
    }
    // If not found in export default, search all call expressions
    if (!buildConfigCall) {
        const callExpressions = sourceFile.getDescendantsOfKind(SyntaxKind.CallExpression);
        buildConfigCall = callExpressions.find((ce)=>{
            const expr = ce.getExpression();
            return expr.getText() === buildConfigName;
        });
    }
    if (!buildConfigCall) {
        return {
            changes: [],
            modified: false
        };
    }
    const configArg = buildConfigCall.getArguments()[0];
    if (!configArg || !Node.isObjectLiteralExpression(configArg)) {
        return {
            changes: [],
            modified: false
        };
    }
    // 1. Remove db property
    if (detection.dbProperty) {
        const dbProperty = configArg.getProperty('db');
        if (dbProperty) {
            dbProperty.remove();
            changes.push('Removed db property');
            modified = true;
        }
    }
    // 2. Remove secret property (platform-managed)
    if (detection.secretProperty) {
        const secretProperty = configArg.getProperty('secret');
        if (secretProperty) {
            secretProperty.remove();
            changes.push('Removed secret property');
            modified = true;
        }
    }
    // 3. Remove editor if default
    if (detection.editorProperty?.isDefault) {
        const editorProperty = configArg.getProperty('editor');
        if (editorProperty) {
            editorProperty.remove();
            changes.push('Removed default editor property');
            modified = true;
        }
    }
    // 4. Remove sharp property
    if (detection.sharpProperty) {
        const sharpProperty = configArg.getProperty('sharp');
        if (sharpProperty) {
            sharpProperty.remove();
            changes.push('Removed sharp property');
            modified = true;
        }
    }
    // 5. Remove sharpTransformer from upload.transformers, then any config it leaves empty
    if (detection.sharpTransformer) {
        const calls = findSharpTransformerCalls(sourceFile, configArg);
        if (calls.length > 0) {
            const transformersArray = calls[0].getParentIfKindOrThrow(SyntaxKind.ArrayLiteralExpression);
            for (const call of calls){
                transformersArray.removeElement(call);
            }
            changes.push('Removed sharpTransformer from upload.transformers');
            const transformersProperty = transformersArray.getParentIfKindOrThrow(SyntaxKind.PropertyAssignment);
            const uploadObject = transformersProperty.getParentIfKindOrThrow(SyntaxKind.ObjectLiteralExpression);
            if (transformersArray.getElements().length === 0) {
                transformersProperty.remove();
            }
            if (uploadObject.getProperties().length === 0) {
                uploadObject.getParentIfKindOrThrow(SyntaxKind.PropertyAssignment).remove();
            }
            modified = true;
        }
    }
    // 6. Update buildConfig import
    if (detection.needsImportChange) {
        if (payloadImport) {
            if (detection.hasOtherPayloadImports) {
                // Remove buildConfig from payload import, add new figma import
                const namedImports = payloadImport.getNamedImports();
                const buildConfigImport = namedImports.find((ni)=>ni.getName() === 'buildConfig');
                if (buildConfigImport) {
                    buildConfigImport.remove();
                    // If payload import is now empty, remove it
                    if (payloadImport.getNamedImports().length === 0) {
                        payloadImport.remove();
                    }
                }
                // Add new import at the top
                sourceFile.addImportDeclaration({
                    moduleSpecifier: '@payloadcms/figma',
                    namedImports: [
                        'buildFigmaConfig'
                    ]
                });
                // Rename all usages of 'buildConfig' to 'buildFigmaConfig'
                const identifiers = sourceFile.getDescendantsOfKind(SyntaxKind.Identifier);
                identifiers.forEach((identifier)=>{
                    if (identifier.getText() === 'buildConfig') {
                        identifier.replaceWithText('buildFigmaConfig');
                    }
                });
                changes.push('Split buildConfig import to @payloadcms/figma');
            } else {
                // Replace entire import: change module specifier and rename all references
                const buildConfigImport = payloadImport.getNamedImports().find((ni)=>ni.getName() === 'buildConfig');
                if (buildConfigImport) {
                    // Change the import name
                    buildConfigImport.setName('buildFigmaConfig');
                    // Find and rename all usages of 'buildConfig' in the file
                    const identifiers = sourceFile.getDescendantsOfKind(SyntaxKind.Identifier);
                    identifiers.forEach((identifier)=>{
                        if (identifier.getText() === 'buildConfig') {
                            identifier.replaceWithText('buildFigmaConfig');
                        }
                    });
                }
                payloadImport.setModuleSpecifier('@payloadcms/figma');
                changes.push('Changed buildConfig import to @payloadcms/figma');
            }
            modified = true;
        }
    }
    // 7. Remove orphaned imports
    // Re-fetch imports after each removal to avoid stale references
    if (detection.dbProperty) {
        const currentImports = sourceFile.getImportDeclarations();
        const dbImport = currentImports.find((imp)=>imp.getModuleSpecifierValue() === detection.dbProperty?.importSource);
        if (dbImport) {
            dbImport.remove();
            changes.push(`Removed ${detection.dbProperty.adapter} import`);
            modified = true;
        }
    }
    if (detection.editorProperty?.isDefault) {
        const currentImports = sourceFile.getImportDeclarations();
        const editorImport = currentImports.find((imp)=>imp.getModuleSpecifierValue() === detection.editorProperty?.importSource);
        if (editorImport) {
            editorImport.remove();
            changes.push('Removed lexicalEditor import');
            modified = true;
        }
    }
    if (detection.sharpProperty) {
        const currentImports = sourceFile.getImportDeclarations();
        const sharpImport = currentImports.find((imp)=>imp.getModuleSpecifierValue() === 'sharp');
        if (sharpImport) {
            sharpImport.remove();
            changes.push('Removed sharp import');
            modified = true;
        }
    }
    if (detection.sharpTransformer) {
        const currentImports = sourceFile.getImportDeclarations();
        const transformerImport = currentImports.find((imp)=>imp.getModuleSpecifierValue() === SHARP_TRANSFORMER_SOURCE);
        if (transformerImport) {
            transformerImport.remove();
            changes.push('Removed sharpTransformer import');
            modified = true;
        }
    }
    return {
        changes,
        modified
    };
}
/**
 * Find `sharpTransformer()` calls in `upload.transformers` of the config object.
 * Returns none when the imported name is used anywhere else, so the import can be
 * removed without breaking other code.
 */ function findSharpTransformerCalls(sourceFile, configArg) {
    const transformerImport = sourceFile.getImportDeclarations().find((imp)=>imp.getModuleSpecifierValue() === SHARP_TRANSFORMER_SOURCE);
    const specifier = transformerImport?.getNamedImports().find((ni)=>ni.getName() === 'sharpTransformer');
    if (!transformerImport || !specifier) {
        return [];
    }
    const localName = specifier.getAliasNode()?.getText() ?? 'sharpTransformer';
    if (!Node.isObjectLiteralExpression(configArg)) {
        return [];
    }
    const upload = configArg.getProperty('upload');
    const uploadObject = Node.isPropertyAssignment(upload) ? upload.getInitializer() : undefined;
    if (!Node.isObjectLiteralExpression(uploadObject)) {
        return [];
    }
    const transformers = uploadObject.getProperty('transformers');
    const transformersArray = Node.isPropertyAssignment(transformers) ? transformers.getInitializer() : undefined;
    if (!Node.isArrayLiteralExpression(transformersArray)) {
        return [];
    }
    const calls = transformersArray.getElements().filter((element)=>Node.isCallExpression(element) && element.getExpression().getText() === localName);
    const references = sourceFile.getDescendantsOfKind(SyntaxKind.Identifier).filter((id)=>id.getText() === localName && !id.getFirstAncestorByKind(SyntaxKind.ImportDeclaration));
    if (references.length !== calls.length) {
        return [];
    }
    return calls;
}
/**
 * Add figma property to buildConfig if it doesn't exist
 * Modifies the AST in memory - caller must call sourceFile.save()
 */ export function addFigmaProperty(sourceFile, config) {
    const changes = [];
    let modified = false;
    // Find buildFigmaConfig call (this function is only used with Figma configs)
    const callExpressions = sourceFile.getDescendantsOfKind(SyntaxKind.CallExpression);
    const buildConfigCall = callExpressions.find((ce)=>{
        const expr = ce.getExpression();
        const text = expr.getText();
        return text === 'buildFigmaConfig' || text.endsWith('.buildFigmaConfig');
    });
    if (!buildConfigCall) {
        log.debug('No buildFigmaConfig call found');
        return {
            changes: [],
            modified: false
        };
    }
    // Get config object argument
    const configArg = buildConfigCall.getArguments()[0];
    if (!configArg || !Node.isObjectLiteralExpression(configArg)) {
        log.debug('buildConfig argument is not an object literal');
        return {
            changes: [],
            modified: false
        };
    }
    // Check if figma property already exists
    const existingFigmaProperty = configArg.getProperty('figma');
    if (existingFigmaProperty) {
        log.debug('figma property already exists, skipping');
        return {
            changes: [
                'Skipped: figma property already exists'
            ],
            modified: false
        };
    }
    // Add figma property
    // contentSystemId is resolved automatically by buildFigmaConfig from env vars or bootstrap cache.
    // useContentSystem defaults to true, so we only generate it when explicitly false.
    const figmaObj = config.useContentSystem === false ? `{\nuseContentSystem: false,\n}` : '{}';
    configArg.addPropertyAssignment({
        name: 'figma',
        initializer: figmaObj
    });
    changes.push(`Added figma property (contentSystemId: ${config.contentSystemId})`);
    modified = true;
    return {
        changes,
        modified
    };
}
/**
 * Remove the contentSystemId property from figma config object.
 * Used during upgrade migration — contentSystemId is now resolved from bootstrap data.
 *
 * @returns true if the property was found and removed
 */ export function removeFigmaContentSystemId(sourceFile) {
    const callExpressions = sourceFile.getDescendantsOfKind(SyntaxKind.CallExpression);
    const buildConfigCall = callExpressions.find((ce)=>{
        const expr = ce.getExpression();
        const text = expr.getText();
        return text === 'buildFigmaConfig' || text.endsWith('.buildFigmaConfig');
    });
    if (!buildConfigCall) {
        return false;
    }
    const configArg = buildConfigCall.getArguments()[0];
    if (!configArg || !Node.isObjectLiteralExpression(configArg)) {
        return false;
    }
    const figmaProperty = configArg.getProperty('figma');
    if (!figmaProperty || !Node.isPropertyAssignment(figmaProperty)) {
        return false;
    }
    const initializer = figmaProperty.getInitializer();
    if (!initializer || !Node.isObjectLiteralExpression(initializer)) {
        return false;
    }
    const contentSystemIdProp = initializer.getProperty('contentSystemId');
    if (!contentSystemIdProp) {
        return false;
    }
    contentSystemIdProp.remove();
    // Collapse empty object to avoid ts-morph whitespace artifacts
    if (initializer.getProperties().length === 0) {
        initializer.replaceWithText('{}');
    }
    return true;
}
